const VELU_INFO={id:"velu-nachiyar",title:"Velu Nachiyar",quickStats:[{label:"Born",value:"1730, Ramnad",icon:"📍"},{label:"Reign Reclaimed",value:"1780",icon:"👑"},{label:"Title",value:"Veeramangai (Brave Woman)",icon:"🛡️"},{label:"Kingdom",value:"Sivaganga",icon:"🏰"},{label:"Known For",value:"Early Armed Resistance to the EIC",icon:"⚔️"},{label:"Died",value:"1796",icon:"🕊️"}]},HISTORY_TEXT={title:"The Queen Who Reclaimed Her Throne",paragraphs:["Velu Nachiyar was born in 1730 to the royal family of Ramnad and was trained in warfare, horse riding, archery, and multiple languages from a young age. She was married to Muthuvaduganathaperiya Udaiyathevar, the ruler of Sivaganga.","In 1772, her husband was killed in battle against combined forces of the British East India Company and the Nawab of Arcot, and Sivaganga fell under their control. Velu Nachiyar fled with her daughter and took refuge under the protection of Hyder Ali, ruler of Mysore, at Virupachi near Dindigul for about eight years.","During her years in exile, she worked to build alliances and raise a fighting force, gathering support from regional allies. In 1780, Velu Nachiyar led a successful military campaign to reclaim the kingdom of Sivaganga from the East India Company's control, ruling for several years afterward.","She is remembered as one of the earliest Indian rulers to organize armed resistance against the East India Company, decades before the wider uprisings of the mid-19th century, and is honored today with the title 'Veeramangai,' meaning 'brave woman.'"]},TIMELINE_EVENTS=[{era:"1730",title:"Born in Ramnad",description:"Velu Nachiyar was born into the royal family of Ramnad and trained in warfare and multiple languages."},{era:"1746 (approx.)",title:"Marriage to the King of Sivaganga",description:"Married Muthuvaduganathaperiya Udaiyathevar, ruler of the Sivaganga kingdom."},{era:"1772",title:"Fall of Sivaganga",description:"Her husband was killed in battle against East India Company and Arcot forces; Sivaganga fell under their control."},{era:"1772–1780",title:"Exile and Alliance-Building",description:"Took refuge under Hyder Ali's protection near Dindigul, building military and political alliances over roughly eight years."},{era:"1780",title:"Reclaiming Sivaganga",description:"Led a successful military campaign to retake the kingdom of Sivaganga from East India Company control."},{era:"1780–1790s",title:"Rule of Sivaganga",description:"Governed Sivaganga following its reclamation, later passing rule to her daughter."},{era:"1796",title:"Death",description:"Velu Nachiyar passed away, remembered as one of India's earliest anti-colonial resistance leaders."}],MILITARY_CAMPAIGNS=[{title:"Alliance-Building in Exile",note:"Spent years gathering regional support and forces while in exile near Dindigul, under Hyder Ali's protection."},{title:"Formation of a Women's Army",note:"Historical accounts credit her with organizing a trained female military regiment, referred to as the 'Udaiyaal army,' named after a loyal commander."},{title:"Campaign to Retake Sivaganga",note:"Led combined regional forces in a coordinated campaign that successfully reclaimed the Sivaganga kingdom in 1780."},{title:"Post-Victory Consolidation",note:"Worked to stabilize and govern the kingdom after reclaiming it, restoring regional administration."}],ALLIANCES=[{title:"Hyder Ali of Mysore",note:"Provided refuge and support during Velu Nachiyar's years in exile near Dindigul."},{title:"Marudu Brothers",note:"Regional chieftains who allied with her and played a significant role in the campaign to reclaim Sivaganga."},{title:"Regional Palayakkarar Chiefs",note:"Local chieftains (Palayakkarars) in the region who supported her coalition against East India Company control."}],GALLERY_QUERIES=["Sivaganga fort Tamil Nadu","Ramnad kingdom historical Tamil Nadu","18th century South Indian warrior queen art"],REFERENCES=[{text:"Tamil Nadu State Archives — historical records of the Sivaganga kingdom.",link:"#"},{text:"Government of India — commemorative postage stamp release documentation (1974).",link:"#"},{text:"Regional historical accounts of the Ramnad and Sivaganga royal families.",link:"#"},{text:"Academic histories of 18th-century South Indian resistance to the East India Company.",link:"#"}];